26-bank_credit","title":"Кредитор лишился лицензии","category":"Финансирование бюджета","format":"animated-svg","version":1,"alt":"Авторская сцена к ситуации «Кредитор лишился лицензии»","media_label":"Бюджетный мониторинг","news_lead":"Бюджетная комиссия обсуждает ситуацию «Кредитор лишился лицензии»."},"source_note":"Авторская учебная ситуация, не сообщение о реальном происшествии. Нормы проверены 02.10.2026; денежные эффекты — параметры игры."}]$authored$::jsonb))
INSERT INTO private.authored_event_catalog(case_key,content)
SELECT doc->>'case_key',doc FROM authored
ON CONFLICT(case_key) DO UPDATE SET content=excluded.content;

UPDATE public.event_cases e SET
 situation=c.content->>'situation',
 decision_options=c.content->'decision_options',
 effect_plan=c.content->'effect_plan',
 allowed_roles=ARRAY(SELECT jsonb_array_elements_text(c.content->'allowed_roles')),
 comic_scene=c.content->'comic_scene',
 status='ready'
FROM private.authored_event_catalog c
WHERE e.case_key=c.case_key AND e.case_key IN ('budget-region-2026-63-technical-college','budget-region-2026-64-wastewater-cleaning','budget-region-2026-72-temporary-family-housing','budget-region-2026-77-recipient-insolvent','budget-risk-2026-bank_credit')
AND NOT EXISTS(SELECT 1 FROM public.event_assignments a WHERE a.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_decisions d WHERE d.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_case_outcomes o WHERE o.case_id=e.id);
